import{_ as e,c as a,o as r,b0 as o}from"./chunks/framework.Dmsv_Tiv.js";const i="/media-docs/assets/ce4d9cb154d8852dff5a2f753b770996.BVvd5vOh.jpg",l="data:image/png;base64,",n="/media-docs/assets/image-20251121104438067.Ch84rwfK.png",s="/media-docs/assets/image-20251121100606723.Db0GdUWd.png",p="/media-docs/assets/image-20251121103712917.CZFWPKpO.png",d="/media-docs/assets/quality_modes.DBgFCn_e.png",h="/media-docs/assets/image-20251218155142567.U5oUyKOx.jpg",R=JSON.parse('{"title":"LV007-基本概念","description":null,"frontmatter":{"title":"LV007-基本概念","date":"2025-11-20T17:06:13.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/vcodec/encode/126b14d2f67532361720554a","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-11-20T17:06:13.803Z","fulluuid":"61720554adf749f785bea046ba9b4a4c","useduuid":"61720554a"}},"headers":[],"relativePath":"sdoc/vcodec/encode/126b14d2f67532361720554a.md","filePath":"sdoc/20-视频编解码/05-编码/LV007-基本概念.md","lastUpdated":1767537778000}'),c={name:"sdoc/vcodec/encode/126b14d2f67532361720554a.md"};function g(u,t,b,P,q,V){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="lv007-基本概念" tabindex="-1">LV007-基本概念 <a class="header-anchor" href="#lv007-基本概念" aria-label="Permalink to &quot;LV007-基本概念&quot;">​</a></h1><h2 id="一、编码格式" tabindex="-1">一、编码格式 <a class="header-anchor" href="#一、编码格式" aria-label="Permalink to &quot;一、编码格式&quot;">​</a></h2><h3 id="_1-谁制定编码标准" tabindex="-1">1. 谁制定编码标准？ <a class="header-anchor" href="#_1-谁制定编码标准" aria-label="Permalink to &quot;1. 谁制定编码标准？&quot;">​</a></h3><p>视频编码标准主要由两个国际组织负责制定：<strong>国际电信联盟 ITU-T</strong> 和 <strong>国际标准化组织 ISO</strong>。目前影响力最强的视频编码标准基本均出自这两个组织。</p><p><strong>国际电信联盟 ITU-T</strong> 制定的标准有 H.261、H.263、H.263+、H.264 等。“<strong>国际标准化组织</strong>（ISO）”它制定的标准有 MPEG-1、MPEG-2、MPEG-4 等。</p><p>除了上述两个组织之外，其他比较有影响力的标准还有：</p><ul><li>Google：VP8/VP9;</li><li>Microsoft : VC-1;</li><li>国产自主标准：AVS/AVS+/AVS2</li></ul><p>ITU-T 的视频编码 <strong>专家组名称</strong> 为：<strong>Video Coding Expert Group， VCEG</strong>。该专家组所建立的标准属于 ITU-T H 系列建议书中视听及多媒体系统的一个组成部分，该组成部分的名称为活动图像编码（Coding of moving video），编号范围为 H.260 – H.279，目前已在进行 H.266 标准的建立。</p><p>ISO/IEC 的视频编码 <strong>专家组名称</strong> 为：<strong>Moving Pictures Experts Group，MPEG</strong>。该专家组所建立的标准命名为 MEPG-x 系列。如 MEPEG-1 MEPG-2 MPEG4。MPEG4 也即是我们常见的 MP4</p><p>ITU-T 和 ISO/IEC 一开始都是各干各的，推出自己的标准，中间也和作过一次推出 H.262/MPEG-2，然而可能是市场反响不是很好，因此又各干各的推出另一个标准，后来再次联合推出了 H.264/AVC 获得巨大的成功，目前互联网上的视频编码基本清一色的是 H.264/AVC。</p><h3 id="_2-编码格式简介" tabindex="-1">2. 编码格式简介 <a class="header-anchor" href="#_2-编码格式简介" aria-label="Permalink to &quot;2. 编码格式简介&quot;">​</a></h3><p>ITU-T for ITU Telecommunication Standardization Sector, 是国际电信联盟管理下的专门制定电信标准的分支机构, 是 H.26X 标准的制定者。</p><ul><li><p><strong>H.261</strong>：主要在老的视频会议和视频电话产品中使用。</p></li><li><p><strong>H.263</strong>：主要用在视频会议、视频电话和网络视频上。</p></li><li><p><strong>H.264</strong>：H.264/MPEG-4 第十部分，又称 AVC（Advanced Video Coding，高级视频编码），是一种视频压缩标准，一种被广泛使用的高精度视频的录制、压缩和发布格式。是目前应用最为广泛的视频编码格式之一，它就像视频编码领域的 “通用语言”，在网络视频、直播、监控、蓝光光盘等众多场景中都能看到它的身影。</p></li><li><p><strong>H.265</strong>：高效率视频编码（High Efficiency Video Coding，简称 HEVC）是一种视频压缩标准，H.264/MPEG-4 AVC 的继任者，其诞生的主要目的就是为了应对日益增长的高清和超高清视频需求。在当今这个 4K 甚至 8K 视频逐渐普及的时代，H.265 发挥着越来越重要的作用。HEVC 被认为不仅提升图像质量，同时也能达到 H.264/MPEG-4 AVC 两倍之压缩率（等同于同样画面质量下比特率减少了 50%），这是目前发展的趋势。</p></li><li><p><strong>MPEG</strong> 全称是 Moving Pictures Experts Group，它是“动态图象专家组”的英文缩写。</p></li></ul><p>（1）MPEG-1 第二部分（MPEG-1 第二部分主要使用在 VCD 上，有些在线视频也使用这种格式。该编解码器的质量大致上和原有的 VHS 录像带相当。）</p><p>（2）MPEG-2 第二部分（MPEG-2 第二部分等同于 H.262，使用在 DVD、SVCD 和大多数数字视频广播系统和有线分布系统（cable distribution systems）中。）</p><p>（3）MPEG-4 第二部分（MPEG-4 第二部分标准可以使用在网络传输、广播和媒体存储上。比起 MPEG-2 和第一版的 H.263，它的压缩性能有所提高。）</p><p>（4）MPEG-4 第十部分（MPEG-4 第十部分技术上和 ITU-T H.264 是相同的标准，有时候也被叫做“AVC”）最后这两个编码组织合作，诞生了 H.264/AVC 标准。ITU-T 给这个标准命名为 H.264，而 ISO/IEC 称它为 MPEG-4 高级视频编码（Advanced Video Coding，AVC）。</p><ul><li><strong>AV1</strong>：是由开放媒体联盟(AOM，Alliance for Open Media)在 2018 年发布的，AV1 的前身是 VP9。AOM 的成员已经涵盖了 Amazon、Cisco、Google、Intel、Microsoft、Mozilla、Netflix、AMD、ARM 和 NVIDIA，它成立的目的是为互联网和其他市场创建一个 <strong>开源</strong> 的视频编解码器(AV1，AOMedia Video codec)，旨在取代 VP9 并成为与 HEVC（H.265）竞争的主要视频编码标准，AV1 压缩率比流行的 H.264 格式高 50%、比 VP9 格式高 20%。</li><li><strong>VP9</strong>：是由 <a href="https://baike.baidu.com/item/Google/86964?fromModule=lemma_inlink" target="_blank" rel="noreferrer">Google</a> 主导开发的开放格式、无使用授权费的视频压缩标准，其开发初期曾命名为 Next Gen Open Video（NGOV，下一代开放视频）与 VP-Next，作为 <a href="https://baike.baidu.com/item/VP8/8983934?fromModule=lemma_inlink" target="_blank" rel="noreferrer">VP8</a> 的后继者于 2013 年 6 月 17 日正式定案，隶属于 <a href="https://baike.baidu.com/item/WebM/2455966?fromModule=lemma_inlink" target="_blank" rel="noreferrer">WebM</a> 开源项目。该标准采用帧间预测、变换编码和运动补偿技术，支持 64×64 宏块划分、1/8 像素精度的复合预测以及 32x32 至 4x4 的多级变换，目标是在相同质量下较 VP8 减少 50%比特率，并提供 10/12 位编码与 HDR 支持。</li></ul><h3 id="_2-编码标准发展历程" tabindex="-1">2. 编码标准发展历程 <a class="header-anchor" href="#_2-编码标准发展历程" aria-label="Permalink to &quot;2. 编码标准发展历程&quot;">​</a></h3><p><img src="'+i+'" alt="img"></p><h2 id="二、帧的基础概念" tabindex="-1">二、帧的基础概念 <a class="header-anchor" href="#二、帧的基础概念" aria-label="Permalink to &quot;二、帧的基础概念&quot;">​</a></h2><p><img src="'+l+'" alt="image-20251120163231360"></p><ul><li><p>I 帧：独立编解码，影响 GOP 组中其他帧的质量，信息比较大，帧大小一般会比较大。</p></li><li><p>P 帧：编解码需要参考其他帧，因为部分信息在前一帧中包含，压缩比较高，帧大小较小。</p></li></ul><blockquote><p>Tips：</p><p>网络中如果丢失某一个 P 帧，则会出现后面的 P 帧无法解码的问题，导致预览卡顿。</p><p>一般而言，1080P 编码下一个 I 帧大概 400K～1M 之间。P 帧可能只有 I 帧的 1/10。</p></blockquote><h2 id="三、图像质量与码率" tabindex="-1">三、图像质量与码率 <a class="header-anchor" href="#三、图像质量与码率" aria-label="Permalink to &quot;三、图像质量与码率&quot;">​</a></h2><h3 id="_1-码率" tabindex="-1">1. 码率 <a class="header-anchor" href="#_1-码率" aria-label="Permalink to &quot;1. 码率&quot;">​</a></h3><p>其实前面已经了解过了，码率就是单位时间内码率的 bit 数。一般单位为 Mbps。码率是编码码率大小的度量单位，一般码率越大，占用越多的存储空间和网络带宽，图像质量越好。</p><p>一些常见场景的码率情况：</p><p><img src="'+n+'" alt="image-20251121104438067"></p><blockquote><p>高复杂场景就类似于森林，花坛这种，画面中存在大量的树叶就会导致出现很多细节，可能会导致码率波动较大。</p></blockquote><h3 id="_2-qp-值" tabindex="-1">2. QP 值 <a class="header-anchor" href="#_2-qp-值" aria-label="Permalink to &quot;2. QP 值&quot;">​</a></h3><p><strong>量化</strong> 就是把信号的连续取值映射成多个离散的幅值的过程，实现了信号取值多对一的映射。</p><p>QP（Quantizer Parameter）量化参数，表明了 <strong>图像空间细节的压缩情况</strong>。QP 值在一定程度上决定了图像质量。现有的码率控制算法主要是通过调整离散余弦变换的量化参数大小输出目标码率。实际上，量化参数（QP）反映了空间细节压缩情况，比如 <strong>QP 值小</strong>，量化越精细，更多细节就会保留，<strong>图像质量越高</strong>；<strong>QP 值越大</strong>，就会丢失更多细节，视频画面的清晰度就会越低，<strong>图像质量越低</strong>。也就是说，QP 和比特率成反比的关系，而且随着视频源复杂度的提高，这种反比关系会更明显。</p><blockquote><p>可以这样理解，QP 值越大，压缩的越厉害，丢掉的画面细节越多，画面越模糊。QP 值越小，丢掉的画面细节越少，画面越清晰。</p></blockquote><p><strong>在编码中，亮度的 QP 最大值是 51、色度的 QP 最大值是 39</strong>，在真正开发中调节亮度的 QP 值为主。取值为 0 时编码细节最为精细，取值为 51 时编码细节最为粗糙。</p><p>我们一般可以通过 QP 来调节编码器的图像质量，从而控制码率。但是一般我们不会取 0 和 51 这种比较极端的 QP，而是根据实际情况去取一个更为合理的范围。如 10 ~ 51.我们把这个范围内的最小 QP 成为 MinQP。最大 QP 称为 MAXQP。</p><h3 id="_3-码率控制" tabindex="-1">3. 码率控制 <a class="header-anchor" href="#_3-码率控制" aria-label="Permalink to &quot;3. 码率控制&quot;">​</a></h3><h4 id="_3-1-定码率-cbr" tabindex="-1">3.1 定码率 CBR <a class="header-anchor" href="#_3-1-定码率-cbr" aria-label="Permalink to &quot;3.1 定码率 CBR&quot;">​</a></h4><p>CBR（Constant Bit Rate），恒定码率，<strong>一定时间范围内比特率基本保持的恒定，不受图像复杂度的影响</strong>。CBR 编码方式可以保证视频的稳定码率，适用于网络带宽固定且稳定的场景，但 <strong>图像质量不能保证</strong>。该编码方式通常用于直播、电视广播等场景。</p><ul><li>优点：码率稳定，容易控制。</li><li>缺点：图像质量不能保证，网络带宽利用率较低，不太适用于网络带宽不稳定的场景。</li></ul><p>码控策略如下图：</p><p><img src="'+s+'" alt="image-20251121100606723"></p><blockquote><p>这种方式只是保证码率始终大致保持不变，并非是完全固定在一个值。</p></blockquote><h4 id="_3-2-可变码率-vbr" tabindex="-1">3.2 可变码率 VBR <a class="header-anchor" href="#_3-2-可变码率-vbr" aria-label="Permalink to &quot;3.2 可变码率 VBR&quot;">​</a></h4><p>VBR（Variable Bitrate Coding），可变比特率编码。是指使用不同的压缩比率来实现画面质量和码率的均衡，是码率运行有一定波动的码控方式。其特点是码率会随着运动场景的复杂程度而增大。</p><p>视频的整体码率是可以根据图像根据动态变化的，能够适应网络带宽的变化情况。通过连续提高和降低视频压缩比，可以减少码率之间的差异，从而提高画面质量。主要用于对码率波动不敏感，需要保障图像质量细节的场景。</p><p>VBR 通常会设置为高中低三档，三档对应的 QP 范围为：高质量：12~35；中质量：18~40；低质量：35~45。</p><ul><li>优点：能够自适应带宽，保证视频画面质量。</li><li>缺点：对传输带宽有较高要求，网络带宽不足时会出现流畅度问题。</li></ul><p>码控策略如下图：</p><p><img src="'+p+'" alt="image-20251121103712917"></p><h5 id="_3-2-1-avbr" tabindex="-1">3.2.1 AVBR <a class="header-anchor" href="#_3-2-1-avbr" aria-label="Permalink to &quot;3.2.1 AVBR&quot;">​</a></h5><p>AVBR（Adaptive Variable Bit rate）变码率：AVBR 是通过对 VBR 的进一步改进，增加了自适应动态码率控制功能。该编码方式会根据网络带宽实时调节码率和分辨率，以尽量保证视频的流畅度和清晰度，同时保证网络带宽的高效利用。它能在网络带宽不稳定的情况下，仍然能保持良好的视频质量和播放效果。</p><ul><li><p>优点：平衡了画面质量和码率，可以在网络带宽不稳定的情况下，自动调整码率以保证视频质量和流畅度。</p></li><li><p>缺点：编码复杂度较高。</p></li></ul><h5 id="_3-2-2-qvbr" tabindex="-1">3.2.2 QVBR <a class="header-anchor" href="#_3-2-2-qvbr" aria-label="Permalink to &quot;3.2.2 QVBR&quot;">​</a></h5><p>QVBR（Quality Variable Bit rate）质量码率：QVBR 在 VBR 的基础上，增加了自适应动态质量控制功能。编码器会根据图像质量目标和帧率等因素自适应调节码率，以确保图像质量。这种编码方式减少了码率的小部分波动对图像质量的影响，进一步提高了图像的清晰度和稳定性。</p><ul><li>优点：能够在保证画面质量的前提下减少码流的波动。</li><li>缺点：需要更高的码率带宽比。</li></ul><h5 id="_3-2-3-cvbr" tabindex="-1">3.2.3 CVBR <a class="header-anchor" href="#_3-2-3-cvbr" aria-label="Permalink to &quot;3.2.3 CVBR&quot;">​</a></h5><p>CVBR（Constrained Variable Bit rate）有限码率：CVBR 也是一种自适应码率控制方式，它着重解决了在带宽有限的情况下，视频流的稳定性和流畅度问题。通过增加编码器与解码器的协作，CVBR 可以可以平衡视频码率和清晰度，保证图像质量。</p><ul><li>优点：平衡想要码流和图像质量的关系，在有限的带宽下提高视频的稳定性。</li><li>缺点：需要更高的编码效率和复杂度。</li></ul><h4 id="_3-3-fixqp" tabindex="-1">3.3 FIXQP <a class="header-anchor" href="#_3-3-fixqp" aria-label="Permalink to &quot;3.3 FIXQP&quot;">​</a></h4><p>FIXQP（固定质量）是一种视频编码方式，它通过使用特定的量化参数（QP，Quantization Parameter）来实现固定质量的视频编码。在 FIXQP 编码方式中，图像的质量是固定的，编码器会尽力保持视频图像质量稳定，同时控制码率达到一定水平。</p><p>这种编码方式适用于对图像质量有较高要求的场景，例如视频剪辑、视频会议等。FIXQP 对视频的码率并没有太多限制，因为它的重点在于保证视频的质量，如果码率过低则会导致视频质量下降的问题。因此，在使用 FIXQP 编码时需要根据实际场景调整码率参数，以保证视频质量和码率能够达到均衡状态。</p><ul><li>优点：</li></ul><p>（1）固定质量，视频质量稳定，适用于对视频质量有较高要求的场景；</p><p>（2）编码简单，对硬件配置要求不高。</p><ul><li>缺点：</li></ul><p>（1）不适用于网络带宽受限，需要控制视频码率的场景；</p><p>（2）比其他编码方式需要更高的码率带宽比，因为保持图像质量需要更大的码率空间</p><h4 id="_3-4-恒定码率系数-crf" tabindex="-1">3.4 恒定码率系数 CRF <a class="header-anchor" href="#_3-4-恒定码率系数-crf" aria-label="Permalink to &quot;3.4 恒定码率系数 CRF&quot;">​</a></h4><p>CRF（Constant Rate Factor，恒定码率系数）是一种“恒定质量”的编码模式，与恒定比特率（CBR）模式相对。基本上能让编码器在整个编码过程中保持恒定的质量。通常，要实现恒定质量，需要会对每种相同类型的帧进行同等程度的压缩，也就是说，丢弃相同（相对）数量的信息。用技术术语来说，就是维持恒定的 QP（量化参数）。量化参数定义了要从给定的像素块（即宏块）中丢弃多少信息。这通常会导致整个序列的比特率出现大幅波动。</p><p>恒定码率系数（CRF）则比前者更为精密。它会对不同的帧进行不同程度的压缩，并根据需要相应地调整 QP，以维持某一水平的感知质量。它通过将运动情况考虑在内来实现这一点。在恒定 QP 模式下，当 QP = 18 时，编码过程会始终保持 QP = 18 不变，无论帧的内容如何（尽管对于不同类型的帧会有一些微小的偏移，但在此可以忽略不计）。而在 CRF = 18 的恒定速率因子模式下，对于高运动帧，它会将 QP 提升至 20（即进行更大程度的压缩），而对于序列中的低运动部分，则将 QP 降低至 16。这本质上改变了比特率随时间的分配方式。</p><p>这里有一张图，展示了两个在不同级别（17、23）的恒定 QP 或 CRF 编码的视频片段的比特率变化：</p><p><img src="'+d+'" alt="img"></p><p>可以看到 CRF 的比特数总是少于 QP，意味着保持质量的同时 CRF 能节省比特。</p><blockquote><p>CRF 适用于获得最佳画质的场景，不适用于需要获得特定的比特率 / 文件大小的场景。</p></blockquote><h3 id="_4-编码评价标准" tabindex="-1">4. 编码评价标准 <a class="header-anchor" href="#_4-编码评价标准" aria-label="Permalink to &quot;4. 编码评价标准&quot;">​</a></h3><p>目前通常评测 <strong>编码器效果的指标</strong> 有两种</p><p>（1）相同输入源, 相同编码器关键配置前提下, 相同码率比较 PSNR。 PSNR，“Peak Signal to Noise Ratio”的缩写，即峰值信噪比，是一种评价图像的客观标准。</p><p>（2）相同输入源, 相同编码器关键配置前提下, 相同码率比较 SSIM。SSIM， “structural similarity index”的缩写，即结构相似性，是一种衡量两幅图像相似度的指标。</p><h3 id="_5-码率调优" tabindex="-1">5. 码率调优 <a class="header-anchor" href="#_5-码率调优" aria-label="Permalink to &quot;5. 码率调优&quot;">​</a></h3><p>（1）想让图像质量更好，就降低 QP</p><p>（2）想要码率更小，可以提高 QP、增大 I 帧间隔</p><p>（3）想要码率更稳定，可以使用定码率 CBR。</p><p>（4）想要图像更稳定，可以使用可变码率 VBR。</p><p>（5）运动剧烈的情况下，可以减少 I 帧与 P 帧的 QP 差。</p><p>（6）纹理复杂的时候，可以降低 QP，使画面保留更多的细节。</p><h2 id="四、采样方式" tabindex="-1">四、采样方式 <a class="header-anchor" href="#四、采样方式" aria-label="Permalink to &quot;四、采样方式&quot;">​</a></h2><p>视频采样的时候，会有 <strong>隔行扫描</strong>(奇偶场/顶底场)和 <strong>逐行扫描</strong> 两种。逐行扫描通常用 &quot;P&quot; 来表示，例如 720p 或 1080p，其中的字母 &quot;P&quot; 表示 &quot;Progressive&quot;。行扫描通常用 &quot;I&quot; 来表示，例如 1080i，其中的字母 &quot;I&quot; 表示 &quot;Interlaced&quot;。下图右侧是逐行扫描，左侧是隔行扫描的效果。</p><p><img src="'+h+'" alt="image-20251218155142567"></p><p>逐行扫描，按照从上到下的顺序依次扫描每一行像素。而隔行扫描是以场为基础，<strong>场</strong> 存在于“隔行扫描”记录的视频中，隔行扫描视频的每帧画面均包含两个场，每一个场又分别含有该帧画面的奇数行扫描线或偶数行扫描线信息，故分别叫奇数场或偶数场，也称顶部场或底部场。</p><p>在实际拍摄时，若使用隔行扫描的格式作记录的话，比如标清中的 PAL 制，NTSC 制，高清中 50i、60i 等，它们在记录信号时，总是会先扫描记录下场（偶数场）信号，再扫描记录上场（奇数场）信号；或者相反。如果先记录下场的，就说是下场优先（偶数场优先），反之叫上场优先（奇数场优先）。这样就导致了上场与下场的图像实际上是有一定时间位移之差的，所以这两场的图像在空间上是不能完全重合的，尤其在拍摄活动画面时，活动主体的位置往往会形成梳状条纹，如上所示。</p><p>场的概念其实原于电视，电视由于要克服信号频率带宽的限制，无法在制式规定的刷新时间内（PAL 制式是 25fps）同时将一帧图象显现在屏幕上，只能将图象分成两个半幅的图像，一先一后地显现，由于刷新速度快，肉眼是看不见地。普通电视都是采用隔行扫描方式。隔行扫描方式是将一帧电视画面分成奇数场和偶数场两次扫描。第一次扫出由 1、3、5、7…等所有奇数行组成的奇数场，第二次扫出由 2、4、6、8…等所有偶数行组成的偶数场（premiere 中称为顶部场 Upper Field 和底部场 Low Field, 关系为 <strong>偶数场 Even field 应对应顶部场 upper field</strong> , <strong>奇数场 odd field 应对应底部场 lower field</strong> ）。这样，每一幅图象经过两场扫描，所有的像素便全部扫完。</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>参数</strong></th><th><strong>逐行扫描</strong></th><th><strong>隔行扫描</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><strong>画面质量</strong></td><td>逐行扫描通过一次性显示整个帧提供流畅清晰的图像。</td><td>隔行扫描可能看起来闪烁或模糊，因为它每帧显示两个独立的场。</td></tr><tr><td style="text-align:center;"><strong>带宽</strong></td><td>使用更多带宽，因为它传输完整帧，增加了数据大小和流媒体负载。</td><td>通过一次只发送半帧，使用更少的带宽，对旧系统更高效。</td></tr><tr><td style="text-align:center;"><strong>梳状效应</strong></td><td>逐行扫描没有梳状效应，因为运动在完整帧中捕获。</td><td>隔行扫描在快速运动时会造成梳状效应，使移动物体看起来撕裂或锯齿状。</td></tr><tr><td style="text-align:center;"><strong>图像分辨率</strong></td><td>逐行扫描在每一帧显示完整分辨率，提供更好的细节和清晰度。</td><td>隔行扫描通过将图像分成两个场来降低有效分辨率。</td></tr><tr><td style="text-align:center;"><strong>显示速度</strong></td><td>显示完整帧可能需要稍长的处理时间，但能提供更流畅的观看体验。</td><td>隔行扫描通过发送部分帧实现更快的显示，但视频可能感觉抖动或不均匀。</td></tr><tr><td style="text-align:center;"><strong>音频-图像同步</strong></td><td>逐行扫描中，音频和视频通常保持完美同步，尤其是在数字平台上。</td><td>隔行扫描有时会导致轻微的同步问题，特别是在编辑或转换素材时。</td></tr></tbody></table><blockquote><p>参考资料：</p><p><a href="https://blog.csdn.net/EasyGBS/article/details/105447942" target="_blank" rel="noreferrer">海康平台推出的 Smart264 编码格式是什么？跟 H264 有什么关系？_samrt 编码-CSDN 博客</a></p><p><a href="https://blog.csdn.net/2202_75840803/article/details/148039604" target="_blank" rel="noreferrer">QP 原理的讲解_编码 qp 值-CSDN 博客</a></p><p><a href="https://blog.csdn.net/weixin_45042833/article/details/130766902" target="_blank" rel="noreferrer">视频编码中 vbr 和 cbr 、avbr、 qvbr 、cvbr、fixqp 优缺点-CSDN 博客</a></p><p><a href="https://aijishu.com/a/1060000000328748" target="_blank" rel="noreferrer">了解速率控制模式：什么是 CBR、VBR、CRF 和 Capped-CRF？ - 极术社区 - 连接开发者与智能计算生态</a></p><p><a href="https://slhck.info/video/2017/02/24/crf-guide.html" target="_blank" rel="noreferrer">CRF Guide (Constant Rate Factor in x264, x265 and libvpx)</a></p><p><a href="https://slhck.info/video/2017/03/01/rate-control.html" target="_blank" rel="noreferrer">理解速率控制模式（x264，x265，vpx）</a></p><p><a href="https://blog.csdn.net/piracymonk/article/details/114318303" target="_blank" rel="noreferrer">隔行扫描与去隔行技术-CSDN 博客</a></p><p><a href="https://www.cnblogs.com/warmbeast/p/5980841.html" target="_blank" rel="noreferrer">概念：P 制, N 制, 奇场, 偶场, 隔行扫描, 逐行扫描 - warmbeast - 博客园</a></p><p><a href="https://blog.csdn.net/ThinPikachu/article/details/129867751" target="_blank" rel="noreferrer">视频编码格式发展史_iso ice 与 itu 联合制定的-CSDN 博客</a></p></blockquote>',94)])])}const E=e(c,[["render",g]]);export{R as __pageData,E as default};
